CREATE DATABASE IF NOT EXISTS ideal_muscat CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ideal_muscat;
CREATE TABLE settings (name VARCHAR(64) PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,failed_attempts INT NOT NULL DEFAULT 0,locked_until DATETIME NULL);
CREATE TABLE entries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kind ENUM('service','project','blog','team','faq') NOT NULL,title VARCHAR(200) NOT NULL,summary TEXT NOT NULL,body MEDIUMTEXT NOT NULL,image VARCHAR(255) NOT NULL DEFAULT '',published TINYINT NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,INDEX(kind,published,sort_order));
CREATE TABLE messages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(254) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
